<?php
/**
 * Bloque: Showroom Info
 * Carpeta: blocks/showroom-info
 * Campos ACF (grupo del bloque):
 * - title (text)
 * - hours (wysiwyg)
 * - left-image / left_image (image)
 * - right-image / right_image (image)
 * - location (text)
 * - url (url)
 */

if ( ! function_exists('get_field') ) {
  echo '<p><em>ACF plugin required.</em></p>';
  return;
}

$section_id = 'showroom-info-' . ( isset($block['id']) ? $block['id'] : uniqid() );
$classes    = 'showroom_info_block';
if (!empty($block['className'])) $classes .= ' ' . esc_attr($block['className']);
if (!empty($block['align']))     $classes .= ' align' . esc_attr($block['align']);

$title    = (string) get_field('title');
$hours    = (string) get_field('hours');

$left_img  = get_field('left-image');  if (!$left_img)  $left_img  = get_field('left_image');
$right_img = get_field('right-image'); if (!$right_img) $right_img = get_field('right_image');

$location = (string) get_field('location');
$btn_url  = (string) get_field('url');

if (!function_exists('sib_img_url')) {
  function sib_img_url($img, $size = 'large') {
    if (is_array($img)) {
      if (!empty($img['sizes'][$size])) return esc_url($img['sizes'][$size]);
      if (!empty($img['url']))          return esc_url($img['url']);
    } elseif (is_numeric($img)) {
      $src = wp_get_attachment_image_src((int)$img, $size);
      if ($src && !empty($src[0])) return esc_url($src[0]);
    } elseif (is_string($img) && filter_var($img, FILTER_VALIDATE_URL)) {
      return esc_url($img);
    }
    return '';
  }
}

$left_url  = sib_img_url($left_img,  'large') ?: sib_img_url($left_img,  'full');
$right_url = sib_img_url($right_img, 'large') ?: sib_img_url($right_img, 'full');
?>
<section id="<?php echo esc_attr($section_id); ?>" class="<?php echo esc_attr($classes); ?>">
  <div class="info_sh_container">
    <div class="info_sh_header">
      <h1 class="font-heading-1"><?php echo $title ? esc_html($title) : 'DONDE EL DISEÑO<br>COBRA VIDA'; ?></h1>
      <div class="font-body-small">
        <div class="font-overline">HORARIOS DE ATENCIÓN</div>
        <?php
          if ($hours) {
            echo wp_kses_post($hours);
          } else {
            if ( current_user_can('edit_posts') ) {
              echo '<div style="opacity:.65">Cargá el campo <em>hours</em> (WYSIWYG) con tus horarios.</div>';
            }
          }
        ?>
      </div>
    </div>

    <div class="info_sh_images">
      <?php if ($left_url): ?>
        <div class="info_sh_image_wrapper info_sh_image_left">
          <img src="<?php echo esc_url($left_url); ?>" alt="<?php echo esc_attr($title ?: 'Imagen izquierda'); ?>" loading="lazy" decoding="async">
        </div>
      <?php endif; ?>

